CREATE TYPE "user_role" AS ENUM (
  'customer',
  'cashier',
  'admin'
);

CREATE TYPE "seat_type" AS ENUM (
  'normal',
  'owner',
  'blocked'
);

CREATE TYPE "booking_status" AS ENUM (
  'held',
  'reserved',
  'paid',
  'expired',
  'cancelled'
);

CREATE TYPE "ticket_type" AS ENUM (
  'adult',
  'child'
);

CREATE TYPE "payment_method" AS ENUM (
  'online',
  'cashier'
);

CREATE TABLE "theatres" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar NOT NULL,
  "city" varchar NOT NULL,
  "address" varchar,
  "phone" varchar
);

CREATE TABLE "halls" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "theatre_id" integer NOT NULL,
  "name" varchar NOT NULL,
  "total_rows" integer NOT NULL,
  "seats_per_row" integer NOT NULL,
  "wheelchair_spaces" integer NOT NULL DEFAULT 0
);

CREATE TABLE "seats" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "hall_id" integer NOT NULL,
  "row_number" integer NOT NULL,
  "seat_number" integer NOT NULL,
  "pos_x" integer,
  "pos_y" integer,
  "type" seat_type NOT NULL DEFAULT 'normal'
);

CREATE TABLE "movies" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "title" varchar NOT NULL,
  "description" text,
  "duration_minutes" integer,
  "genre" varchar,
  "age_rating" varchar,
  "poster_url" varchar,
  "trailer_url" varchar,
  "published" boolean NOT NULL DEFAULT false
);

CREATE TABLE "screenings" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "movie_id" integer NOT NULL,
  "hall_id" integer NOT NULL,
  "starts_at" timestamptz NOT NULL,
  "base_price" decimal(6,2) NOT NULL,
  "is_premiere" boolean NOT NULL DEFAULT false,
  "published" boolean NOT NULL DEFAULT false
);

CREATE TABLE "users" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar NOT NULL,
  "email" varchar UNIQUE NOT NULL,
  "password_hash" varchar NOT NULL,
  "role" user_role NOT NULL DEFAULT 'customer',
  "theatre_id" integer,
  "active" boolean NOT NULL DEFAULT true
);

CREATE TABLE "bookings" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "reference" varchar UNIQUE NOT NULL,
  "user_id" integer,
  "guest_email" varchar,
  "screening_id" integer NOT NULL,
  "status" booking_status NOT NULL,
  "hold_expires_at" timestamptz,
  "payment_deadline" timestamptz,
  "total_price" decimal(8,2),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "booking_has_owner" CHECK (user_id IS NOT NULL OR guest_email IS NOT NULL)
);

CREATE TABLE "tickets" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "booking_id" integer NOT NULL,
  "screening_id" integer NOT NULL,
  "seat_id" integer,
  "is_wheelchair" boolean NOT NULL DEFAULT false,
  "ticket_type" ticket_type NOT NULL,
  "price" decimal(6,2) NOT NULL,
  "discount_note" varchar
);

CREATE TABLE "payments" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "booking_id" integer NOT NULL,
  "method" payment_method NOT NULL,
  "stripe_session_id" varchar,
  "amount" decimal(8,2) NOT NULL,
  "paid_at" timestamptz,
  "cashier_id" integer
);

CREATE UNIQUE INDEX ON "seats" ("hall_id", "seat_number");

CREATE UNIQUE INDEX ON "tickets" ("screening_id", "seat_id");

ALTER TABLE "halls" ADD FOREIGN KEY ("theatre_id") REFERENCES "theatres" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "seats" ADD FOREIGN KEY ("hall_id") REFERENCES "halls" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "screenings" ADD FOREIGN KEY ("movie_id") REFERENCES "movies" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "screenings" ADD FOREIGN KEY ("hall_id") REFERENCES "halls" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "users" ADD FOREIGN KEY ("theatre_id") REFERENCES "theatres" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "bookings" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "bookings" ADD FOREIGN KEY ("screening_id") REFERENCES "screenings" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "tickets" ADD FOREIGN KEY ("booking_id") REFERENCES "bookings" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "tickets" ADD FOREIGN KEY ("screening_id") REFERENCES "screenings" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "tickets" ADD FOREIGN KEY ("seat_id") REFERENCES "seats" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "payments" ADD FOREIGN KEY ("booking_id") REFERENCES "bookings" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "payments" ADD FOREIGN KEY ("cashier_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "screenings" ADD CONSTRAINT "published_needs_price" CHECK (published = false OR base_price > 0);
